import {W} from './worked.js';
export const newLessons=[
{id:'z1',ch:0,title:'Đơn vị và bài hiệu năng phối hợp',pages:[16,27],body:'Một byte có 8 bit; Mbps là triệu bit mỗi giây theo quy ước thập phân trong đề. Trễ end-to-end cộng theo từng link và router. Thông lượng bị giới hạn bởi nút thắt, kể cả phần dung lượng chia cho các kết nối cạnh tranh. Khi bài cho nhiều loại trễ, lập bảng từng thành phần rồi cộng, không lấy thông lượng thay tốc độ lan truyền.',memory:'1 byte=8 bit; end-to-end = tổng các trễ trên tuyến',analogy:'Cuộn thư đi qua nhiều trạm: thời gian viết lên đường, chạy trên đường và xử lý ở trạm là ba khoản khác nhau. Ví dụ này không có nghĩa gói tin là vật thể di chuyển với tốc độ xe.'},
{id:'z2',ch:1,title:'Đọc phương thức và so sánh phiên HTTP',pages:[27,38],body:'Trong request line, GET là phương thức; đường dẫn và phiên bản là các phần riêng. Khi tính HTTP cần ghi rõ persistent hay non-persistent, có pipeline/parallel/cache hay không. Với kết nối persistent không pipeline, một lần bắt tay rồi request/response nối tiếp có số RTT khác với mở một TCP riêng cho từng đối tượng. DNS cache có thời hạn TTL, không đảm bảo thấy ngay thay đổi ở authoritative server.',memory:'Đếm bắt tay, lượt request/response và thời gian phát riêng',analogy:'Dùng lại đường giao liên giống giữ kết nối; mở đường mới cho từng cuộn thư giống non-persistent. Phép so sánh không thay thế việc đếm RTT thực tế.'},
{id:'z3',ch:2,title:'Đọc gói và giải bài giao vận phối hợp',pages:[18,65],body:'Đọc từng trường header theo độ dài quy định trước khi suy luận ứng dụng. Checksum nhận phải cộng cả word checksum bằng phép cộng bù 1. TCP ACK chỉ tới byte đầu còn thiếu trong chuỗi liên tục; rwnd, cwnd và dữ liệu chưa ACK là các giới hạn khác nhau. Khi timeout quá ngắn có thể truyền lại dù gói không mất, nên số thứ tự và loại trùng vẫn cần thiết.',memory:'ACK ≠ số byte trong buffer; gửi thêm ≤ min(rwnd,cwnd)−Flight',analogy:'Trạm nhận có thể giữ thư đến sớm nhưng vẫn chờ phần bị thiếu. Kho còn chỗ không có nghĩa đường đi còn tải; đây là hai giới hạn khác nhau.'},
{id:'z4',ch:3,title:'Đọc bảng tuyến, ICMP và trường mảnh cuối',pages:[44,84],body:'ICMP type và code phải được đọc cùng nhau: ví dụ type 3/code 3 báo không tới được cổng. Bảng tuyến phân biệt mạng kết nối trực tiếp với mạng cần next hop. Trong phân mảnh, dữ liệu gốc không gồm header; mỗi mảnh có header riêng, offset tính theo 8 byte. Mảnh cuối có MF=0; độ dài và offset của nó phụ thuộc tổng dữ liệu đã đưa vào các mảnh trước.',memory:'Mảnh cuối: MF=0; offset=payload trước đó/8',analogy:'Các mảnh cuộn thư giữ chung ID, ghi vị trí và dấu còn phần tiếp. Đây là hình dung để nhớ; router không đọc ý nghĩa nội dung cuộn thư.'}
].map(l=>({...l,refs:[l.pages],questions:[]}));
const q=(id,ch,lesson,level,kind,pages,text,options,correct,explain,retry,extra={})=>({id,ch,lesson,level,kind,pages,text,options,correct,explain,retry,objective:id,sourceKind:'authored',hints:['Xác định đúng đại lượng và giả thiết trong đề.',explain],...extra});
export const advancedQuestions=[
q('v3-1-1',0,'z1',1,'theory',[16,16],'Một byte tương ứng bao nhiêu bit?',['1','8','1000','1024'],1,'Một byte có 8 bit. Phải nhân 8 khi đưa số byte vào công thức dùng R theo bit/s.','Muốn biểu diễn một byte bằng các bit, cần bao nhiêu bit?',{shortAnswers:['8','8 bit','tam bit']}),
q('v3-1-2',0,'x1d',2,'scenario',[16,16],'ρ=La/R lớn hơn 1 kéo dài, bộ đệm hữu hạn. Kết quả nào có thể xảy ra?',['Hàng đợi tăng rồi có thể mất gói','Trễ lan truyền tự giảm về 0','Link tự tăng R theo số gói','Mọi gói tự đổi sang TCP'],0,'Gói đến trung bình nhanh hơn khả năng phục vụ nên hàng đợi tăng. Khi bộ đệm đầy, gói có thể bị bỏ; ρ không điều khiển tốc độ tín hiệu.','Bộ đệm hữu hạn sẽ ra sao khi tốc độ bit tới liên tục vượt tốc độ bit đi?'),
q('v3-1-3',0,'z1',4,'calculation',[26,26],'Gói 1000 byte qua 2 link cùng 1 Mbps, dài 6000 km và 3000 km; s=2,5×10⁸ m/s. Switch xử lý 2 ms, không hàng đợi. Tổng trễ bao nhiêu ms?',['52 ms','54 ms','38 ms','36 ms'],1,'Truyền hai link mất 8+8=16 ms; lan truyền mất 24+12=36 ms. Cộng xử lý 2 ms được 54 ms.','Cộng đủ truyền, lan truyền và xử lý cho gói 1000 byte qua tuyến 6000 km + 3000 km đã cho.',{sourceKind:'source-exercise-adapted',mathFamily:'delay',worked:W('1000 byte; R₁=R₂=1 Mbps; d₁=6000 km; d₂=3000 km; s=2,5×10⁸ m/s; xử lý 2 ms.','L: bit/gói; R: bit/s; d: m; s: m/s; t_proc: xử lý.','L=8000 bit; R=10⁶ bit/s; d₁=6×10⁶ m; d₂=3×10⁶ m.','T=L/R₁+L/R₂+d₁/s+d₂/s+t_proc','8+8+24+12+2','54 ms')}),
q('v3-1-4',0,'l4',4,'calculation',[17,27],'10 kết nối chia đều link lõi 10 Mbps, mỗi kết nối có Rs=4 Mbps, Rc=2 Mbps. Tệp 8 megabit qua một kết nối mất xấp xỉ bao nhiêu giây?',['2 s','4 s','8 s','0,8 s'],2,'Mỗi kết nối nhận tối đa min(4,2,10/10)=1 Mbps. Tệp 8 megabit cần 8/1=8 giây, bỏ khởi động và chi phí khác.','Khi link lõi 10 Mbps được 10 kết nối chia đều, tính thời gian cho tệp 8 megabit ở một kết nối.',{mathFamily:'throughput',worked:W('n=10; R=10 Mbps; Rs=4; Rc=2 Mbps; F=8 Mb.','B: thông lượng/kết nối; F: bit tệp.','Các Mbps/Mb dùng thập phân, tỷ số ra giây.','B=min(Rs,Rc,R/n); t=F/B','B=min(4,2,1)=1; t=8/1','8 s')}),
q('v3-2-1',1,'z2',1,'theory',[30,31],'Trong dòng GET /index.html HTTP/1.1, phần nào là phương thức?',['GET','/index.html','HTTP/1.1','Host'],0,'GET là method. Đường dẫn chỉ đối tượng, còn HTTP/1.1 chỉ phiên bản giao thức.','Tên thao tác trong request line GET /index.html HTTP/1.1 là phần nào?',{shortAnswers:['GET']}),
q('v3-2-2',1,'z2',2,'scenario',[27,29],'Client nhận HTML rồi tải thêm hai ảnh qua cùng TCP vẫn mở, không tạo TCP mới. Mô tả kết nối nào phù hợp?',['Persistent HTTP','Non-persistent một TCP/đối tượng','Không thể dùng HTTP','SMTP persistent'],0,'Persistent HTTP cho phép dùng lại TCP để gửi nhiều đối tượng. Không được suy rằng giữ kết nối nghĩa là không còn request/response.','Một TCP phục vụ cả HTML và các ảnh tiếp theo thuộc cách dùng kết nối HTTP nào?'),
q('v3-2-3',1,'z2',4,'calculation',[27,29],'Ba đối tượng, mỗi đối tượng phát 5 ms, RTT=40 ms. So sánh non-persistent tuần tự với persistent không pipeline (1 RTT bắt tay + 1 RTT/đối tượng). Persistent tiết kiệm bao nhiêu ms?',['40 ms','80 ms','120 ms','160 ms'],1,'Non-persistent cần 3×(2×40+5)=255 ms. Persistent cần (1+3)×40+15=175 ms, tiết kiệm 80 ms theo mô hình đã cho.','Với ba đối tượng và RTT=40 ms, cách giữ một TCP tiết kiệm bao nhiêu so với ba TCP nối tiếp theo giả thiết đề?',{mathFamily:'http',worked:W('N=3; RTT=40 ms; phát 5 ms/đối tượng.','T_np: không giữ kết nối; T_p: giữ kết nối; Δ: thời gian tiết kiệm.','Đều theo ms; tổng phát=15 ms.','T_np=N(2RTT+tx); T_p=(N+1)RTT+Ntx; Δ=T_np−T_p','255−175','80 ms')}),
q('v3-2-4',1,'l13',3,'scenario',[55,56],'Resolver có bản ghi IP cũ với TTL còn hiệu lực. Authoritative vừa đổi IP; chưa có cơ chế chủ động xóa cache. Client hỏi resolver có thể nhận gì?',['IP cũ trong cache cho tới khi cần làm mới','Chắc chắn IP mới ngay lập tức','Không bao giờ có IP mới nữa','TCP tự đổi bản ghi DNS'],0,'Cache còn hạn có thể tiếp tục trả bản ghi cũ. TTL giới hạn thời gian cache; đổi ở authoritative không tự buộc mọi cache cập nhật ngay.','Sau khi authoritative đổi địa chỉ, cache DNS còn hạn có bắt buộc trả IP mới ngay không?',{supplementary:['dnsTTL']}),
q('v3-3-1',2,'z3',1,'theory',[22,22],'UDP header mở đầu bằng source port 1110000100000000 và destination port 0000000000011001 (nhị phân). Cặp cổng thập phân là?',['57600 và 25','25 và 57600','225 và 19','65535 và 80'],0,'Source port là 0xE100=57600; destination port là 0x0019=25. Không đảo thứ tự hai trường hoặc nhầm hex với thập phân.','Chuyển hai trường cổng UDP E100 và 0019 (hex) sang thập phân, giữ đúng thứ tự nguồn–đích.',{sourceKind:'source-exercise-adapted',shortAnswers:['57600;25','57600 va 25']}),
q('v3-3-2',2,'l17',2,'scenario',[35,35],'Timer quá ngắn hết hạn trước khi ACK hợp lệ tới, dù gói đã được nhận. Cơ chế nào tránh giao payload trùng cho ứng dụng?',['Nhận diện số thứ tự, bỏ dữ liệu trùng và ACK lại','Luôn giao lại payload lần hai','Bỏ trường sequence number','Tăng TTL thành vô hạn'],0,'Timeout có thể gây phát lại không cần thiết. Sequence number cho receiver nhận diện bản sao và không giao dữ liệu hai lần.','Khi timeout sớm gây gửi lại một gói đã tới, receiver dựa vào cách nào để không giao trùng?'),
q('v3-3-3',2,'l16',4,'calculation',[22,22],'Ba word nhận 253A 17B4 C321 (hex), đã gồm checksum. Tổng bù 1 cuối và nhận xét nào đúng?',['0010: phát hiện lỗi','FFFF: không phát hiện lỗi','1000F: hợp lệ vì không cộng vòng','0000: chắc chắn không có lỗi'],0,'253A+17B4+C321=1000F hex. Cộng vòng bit nhớ được 0010, khác FFFF nên phát hiện lỗi.','Cộng vòng ba word 253A, 17B4, C321 đã gồm checksum sẽ cho kết luận nào?',{sourceKind:'source-exercise-adapted',mathFamily:'checksum',shortAnswers:['0010; phat hien loi','0x0010; phat hien loi'],worked:W('253A,17B4,C321 đã gồm checksum.','S: tổng bù 1 bên nhận.','Dùng hex 16 bit.','S=fold16(Σwords); hợp lệ nếu S=FFFF','1000F → 000F+1=0010','0010, phát hiện lỗi')}),
q('v3-3-4',2,'z3',4,'calculation',[51,58],'TCP nhận Seq=1000 dài 400 byte, mất đoạn 1400–1699 nhưng đã có 1700–1899. rwnd=3000, cwnd=2000, đang bay 1200 byte. ACK và số byte gửi thêm tối đa là?',['1400; 800','1900; 800','1400; 1800','1399; 2000'],0,'Byte đầu thiếu là 1400 nên ACK=1400. Giới hạn gửi thêm=max(0,min(3000,2000)−1200)=800 byte.','Tìm byte thiếu đầu tiên và lượng gửi thêm theo hai cửa sổ trong tình huống TCP đã cho.',{mathFamily:'tcpWindow',shortAnswers:['1400;800'],shortPrompt:'TCP nhận byte 1000–1399 và 1700–1899, thiếu 1400–1699. rwnd=3000, cwnd=2000, đang bay=1200 byte. Nhập ACK; số byte gửi thêm.',worked:W('Đã nhận 1000–1399 và 1700–1899; rwnd=3000,cwnd=2000,Flight=1200 byte.','ACK: byte đầu thiếu; A: có thể gửi thêm.','Cửa sổ và Flight cùng byte; Seq là thứ tự byte.','ACK=byte thiếu đầu; A=max(0,min(rwnd,cwnd)−Flight)','ACK=1400; A=2000−1200','1400; 800')}),
q('v3-4-1',3,'z4',1,'theory',[50,50],'ICMP type 3, code 3 trong bảng tài liệu báo điều gì?',['Không tới được cổng đích','Echo reply','TTL hết hạn','Không tìm được tên miền DNS'],0,'Type 3 là destination unreachable; code 3 chỉ cổng không tới được. Echo reply là type 0, TTL hết hạn thường là type 11.','Thông báo ICMP destination unreachable với code 3 chỉ vấn đề ở mức nào?',{shortAnswers:['cong','port','cong dich','khong toi duoc cong dich']}),
q('v3-4-2',3,'x4c',2,'scenario',[59,60],'Bảng R1 ghi 192.168.10.0/24 là Connected–Fa0/0. Gửi tới 192.168.10.8 qua tuyến này thì đầu ra nào phù hợp?',['Fa0/0 nối mạng trực tiếp','Bắt buộc qua next hop R2 ở serial','DNS resolver','Không thể chuyển tiếp nếu không có BGP'],0,'Mạng đích được kết nối trực tiếp ở Fa0/0 nên dùng interface đó. BGP hay DNS không phải điều kiện để chuyển tiếp tới mạng trực tiếp.','Tra tuyến Connected–Fa0/0 của mạng 192.168.10.0/24 để chọn đầu ra cho host .8.'),
q('v3-4-3',3,'z4',4,'calculation',[84,84],'Datagram 3000 byte, header 20 byte, MTU=500, DF=0. Bộ (total length, offset, MF) của mảnh cuối là?',['120; 360; 0','100; 2880; 0','120; 360; 1','500; 0; 0'],0,'Payload=2980; mỗi mảnh không cuối chứa 480 byte. Sáu mảnh đầu chở 2880 byte; còn 100 byte, nên mảnh cuối length=120, offset=2880/8=360 và MF=0.','Sau sáu mảnh payload 480 byte của datagram 3000 byte, trường của mảnh cuối có giá trị gì?',{sourceKind:'source-exercise-adapted',mathFamily:'fragment',shortAnswers:['120;360;0'],shortPrompt:'IPv4 total=3000 byte, header mỗi mảnh 20 byte, MTU=500 byte, DF=0. Tự tính rồi nhập total length; offset; MF của mảnh cuối.',worked:W('T=3000,H=20,MTU=500 byte,DF=0.','D: payload; C: payload/mảnh; o: offset khối 8 byte.','D=2980; C=floor(480/8)×8=480.','D_last=D−6C; length_last=D_last+H; o_last=6C/8','2980−2880=100; length=120; offset=360; MF=0','120; 360; 0')}),
q('v3-4-4',3,'l27',4,'scenario',[76,79],'Đồ thị vô hướng x–y=2, y–z=1, x–z=7. Khi y–z tăng lên 10, đường tốt nhất x tới z sau hội tụ là?',['Trực tiếp x–z, chi phí 7','Qua y, chi phí 3 như cũ','Qua y, chi phí 12','Không còn đường nào'],0,'Trước thay đổi, qua y tốn 3. Sau thay đổi, qua y tốn 12, lớn hơn cạnh trực tiếp 7; các ước lượng cần được cập nhật theo thông tin mới.','Sau khi cạnh y–z đổi từ 1 lên 10, so đường trực tiếp 7 với đường qua y để chọn tuyến x tới z.')
];
